#!/usr/bin/env python3
"""Generate one thin wrapper per Luau source file, inside LuauLib/Generated.

Why this exists
---------------
Luau should be compiled by UBT like any other module source - that is how Unreal
integrates self-contained third-party code (see Engine/Source/ThirdParty/nanosvg for
the same pattern) and it avoids asking every developer to run CMake first.

The catch: Luau's sources live in the ../Luau submodule, and UBT only compiles sources
that sit inside the module directory. Luau also has no official single-file aggregation
(unlike Lua's onelua.c), and a naive unity build breaks because three file-scope names
are declared `static` in more than one file:

    createmetatable  VM/src/lstrlib.cpp, VM/src/lveclib.cpp
    period           Common/src/TimeTrace.cpp, VM/src/lperf.cpp
    run              VM/src/lapi.cpp, VM/src/lgc.cpp, VM/src/lvmload.cpp

Separate TUs is fine with those; one merged TU is a redefinition error.

So each generated wrapper is just an #include of one Luau source, keeping every source
in its own translation unit while putting a compilable file where UBT can see it.

Re-run this script whenever the Luau submodule changes (files added/removed/renamed),
and commit the result. Usage:

    python GenerateWrappers.py
"""

from pathlib import Path

LIB_DIR = Path(__file__).resolve().parent
LUAU_DIR = LIB_DIR.parent / "Luau"
OUT_DIR = LIB_DIR / "Generated"

# Whole groups, not hand-picked files: upstream reorganizes these freely (release/743
# moved BytecodeBuilder.cpp out of Compiler/src into the new Bytecode/src, which is
# exactly how it dropped out of the build), so let the directory be the source of truth
# and take everything in it. A group that is not listed here is one we never call into -
# Analysis (type checker), CodeGen (JIT), CLI, Require, Inliner, tests are all excluded
# on purpose.
#
# Bytecode is in because Compiler.cpp cannot link without BytecodeBuilder.cpp, which is
# also where the FFlags it declares (LuauEmitCallFeedback, LuauCompileRefactorFeedback,
# LuauCompileFastpcall) are defined. BytecodeDump / BytecodeGraph / Sccp come along for
# the ride - only the JIT inliner and the test suite use them, but they cost three
# translation units and keep the group honest.
GROUPS = ["VM", "Compiler", "Ast", "Common", "Bytecode"]

HEADER = """// Generated by LuauLib/GenerateWrappers.py - do not edit by hand.
//
// Keeps this Luau source in its own translation unit. See GenerateWrappers.py for
// why Luau cannot simply be unity-built.
"""


def main() -> None:
    if not LUAU_DIR.is_dir():
        raise SystemExit(f"Luau submodule not found at {LUAU_DIR}")

    OUT_DIR.mkdir(exist_ok=True)

    # Drop stale wrappers so removed/renamed Luau files do not linger.
    for stale in OUT_DIR.glob("*.cpp"):
        stale.unlink()

    sources = []
    for group in GROUPS:
        src_root = LUAU_DIR / group / "src"
        if not src_root.is_dir():
            # Say so instead of skipping quietly: an upstream rename that moves a group
            # is exactly the failure this script exists to catch.
            print(f"WARNING: no {src_root} - did upstream rename or drop '{group}'?")
            continue
        sources += sorted(src_root.rglob("*.cpp"))

    written = 0
    for source in sources:
        # Wrapper name is "<top-level Luau group>_<stem>".
        group = source.relative_to(LUAU_DIR).parts[0]
        path = source.relative_to(LUAU_DIR).as_posix()
        wrapper = OUT_DIR / f"{group}_{source.stem}.cpp"
        wrapper.write_text(
            f'{HEADER}\n#include "../../Luau/{path}"\n',
            encoding="utf-8",
            newline="\n",
        )
        written += 1

    print(f"wrote {written} wrappers to {OUT_DIR}")


if __name__ == "__main__":
    main()
